def esc(s):
    return s.replace("'", "\\'").replace('"', '\\"').replace('&', '&amp;').replace('<', '&lt;')


for folder, idx in (('values', 0), ('values-ru', 1), ('values-uk', 2)):
    lines = ['<?xml version="1.0" encoding="utf-8"?>', '<resources>']
    for k, v in S.items():
        lines.append('    <string name="%s">%s</string>' % (k, esc(v[idx]).replace('\n', '\\n')))
    lines.append('</resources>')
    os.makedirs(os.path.join(RES, folder), exist_ok=True)
    open(os.path.join(RES, folder, 'strings.xml'), 'w', encoding='utf-8', newline='\n').write('\n'.join(lines) + '\n')
print(len(S), 'строк')
